<?php
namespace App\Domain\Articles;
use App\Models\Article; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
final class ArticleManager { public function save(array $data,?Article $item,int $userId):Article{return DB::transaction(function()use($data,$item,$userId){ $data['reading_time_minutes']=max(1,(int)ceil(str_word_count(strip_tags((string)$data['body']))/200));$item??=new Article;$data['updated_by']=$userId;if(!$item->exists){$data['created_by']=$userId;$data['status']='draft';$data['display_order']=(int)Article::max('display_order')+1;}else{unset($data['status']);}$item->fill($data)->save();return $item;});} public function publish(Article $item):void{$item->update(['status'=>'published','published_at'=>now(),'scheduled_for'=>null,'archived_at'=>null]);} public function schedule(Article $item,string $utc):void{$item->update(['status'=>'scheduled','scheduled_for'=>$utc,'published_at'=>null,'archived_at'=>null]);} public function unpublish(Article $item):void{$item->update(['status'=>'draft','published_at'=>null,'scheduled_for'=>null,'archived_at'=>null]);} public function archive(Article $item):void{if(app(ArticleDependencyInspector::class)->inspect($item)['blocked']){throw \Illuminate\Validation\ValidationException::withMessages(['item'=>'Resolve canonical references before archiving.']);}$item->update(['status'=>'archived','archived_at'=>now(),'published_at'=>null,'scheduled_for'=>null]);} public function restore(Article $item):void{$item->update(['status'=>'draft','archived_at'=>null,'published_at'=>null,'scheduled_for'=>null]);} public function duplicate(Article $item,int $userId):Article{$copy=$item->replicate(['status','published_at','scheduled_for','archived_at','created_by','updated_by']); $copy->slug=$this->uniqueSlug($item->slug.'-copy');$copy->title.=' (Copy)';$copy->status='draft';$copy->created_by=$copy->updated_by=$userId;$copy->display_order=(int)Article::max('display_order')+1;$copy->save();return $copy;} public function move(Article $item,string $direction):void{DB::transaction(function()use($item,$direction){$peer=Article::where('display_order',$direction==='up'?'<':'>',$item->display_order)->orderBy('display_order',$direction==='up'?'desc':'asc')->first();if($peer){$order=$item->display_order;$item->update(['display_order'=>$peer->display_order]);$peer->update(['display_order'=>$order]);}});} private function uniqueSlug(string $base):string{$base=Str::slug($base)?:'article';$slug=$base;for($i=2;Article::where('slug',$slug)->exists();$i++){$slug="$base-$i";}return $slug;} }
